"""S-box proxy designs (about 400 to 2700 gates) end to end with the bundled Python solver. These are proxies generated by
bench/gen_sbox_proxy.py, not the R20 netlists."""
import pytest
import glitchsat_sat as S

EXPECT = {'unprot': 1, 'par': 1, 'par2': 1, 'dmr': 2, 'tmr': 2, 'tmr2': 3,
          'unprots': 1, 'pars': 1, 'par2s': 1, 'dmrs': 2}


@pytest.mark.parametrize('kind', sorted(EXPECT))
def test_minimum(kind, proxies):
    path, top, p = proxies[kind]
    nl = S.gs.Netlist(path, top)
    kw = dict(goal_out=p['goal_out'], goal_value=p['goal_value'], key=p['key'])
    assert S.honest_boots(nl, p['cycles'], **kw) is True
    rows, info, found = S.sweep(nl, p['cycles'], 3, backend='py', **kw)
    m = EXPECT[kind]
    assert [r['verdict'] for r in rows] == ['NO_ATTACK_UP_TO_BOUND'] * m + ['ATTACK_FOUND'] * (4 - m)
    assert len(found['faults']) == m


def test_dmr_same_answer_without_collapsing_k1(proxies):
    """The two-copy design: no 1-flip attack also when every site keeps its own fault variable (shared-mux variant)."""
    path, top, p = proxies['dmrs']
    nl = S.gs.Netlist(path, top)
    kw = dict(goal_out=p['goal_out'], goal_value=p['goal_value'], key=p['key'])
    v, info, res = S.solve(nl, p['cycles'], 1, backend='py', collapse=False, **kw)
    assert v == 'NO_ATTACK_UP_TO_BOUND' and info['fault_vars'] == info['sites_modelled']
    v, info, res = S.solve(nl, p['cycles'], 3, backend='py', collapse=False, fault_enc='relax', **kw)
    assert v == 'ATTACK_FOUND' and len(res['faults']) == 2 and info['minimum_proved']
